export interface ViewportPoint {
  x: number;
  y: number;
}

export interface ViewportDimensions {
  width: number;
  height: number;
}

export interface MapTransform {
  scale: number;
  rotationDeg: number;
  translation: ViewportPoint;
}

export interface PinchRotateInput {
  scaleFactor: number;
  rotationDeltaDeg: number;
  focal: ViewportPoint;
  viewport: ViewportDimensions | null | undefined;
}

export const MIN_VIEWPORT_SCALE = 0.5;
export const MAX_VIEWPORT_SCALE = 4;

const DEFAULT_TRANSFORM: MapTransform = {
  scale: 1,
  rotationDeg: 0,
  translation: { x: 0, y: 0 },
};

const EPSILON = 1e-6;

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function toRadians(degrees: number): number {
  return (degrees * Math.PI) / 180;
}

function rotatePoint(point: ViewportPoint, angleRad: number): ViewportPoint {
  const cos = Math.cos(angleRad);
  const sin = Math.sin(angleRad);

  return {
    x: point.x * cos - point.y * sin,
    y: point.x * sin + point.y * cos,
  };
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

function isValidViewport(viewport: ViewportDimensions | null | undefined): viewport is ViewportDimensions {
  return (
    !!viewport &&
    isFiniteNumber(viewport.width) &&
    isFiniteNumber(viewport.height) &&
    viewport.width > 0 &&
    viewport.height > 0
  );
}

function clampFocalPoint(focal: ViewportPoint, viewport: ViewportDimensions): ViewportPoint {
  if (!isFiniteNumber(focal.x) || !isFiniteNumber(focal.y)) {
    return {
      x: viewport.width / 2,
      y: viewport.height / 2,
    };
  }

  return {
    x: clamp(focal.x, 0, viewport.width),
    y: clamp(focal.y, 0, viewport.height),
  };
}

export function createInitialMapTransform(): MapTransform {
  return {
    scale: DEFAULT_TRANSFORM.scale,
    rotationDeg: DEFAULT_TRANSFORM.rotationDeg,
    translation: { ...DEFAULT_TRANSFORM.translation },
  };
}

export function clampViewportScale(scale: number): number {
  if (!isFiniteNumber(scale)) {
    return DEFAULT_TRANSFORM.scale;
  }

  return clamp(scale, MIN_VIEWPORT_SCALE, MAX_VIEWPORT_SCALE);
}

export function normalizeRotationDeg(rotationDeg: number): number {
  if (!isFiniteNumber(rotationDeg)) {
    return DEFAULT_TRANSFORM.rotationDeg;
  }

  return ((((rotationDeg + 180) % 360) + 360) % 360) - 180;
}

export function worldFromScreen(screenPoint: ViewportPoint, transform: MapTransform): ViewportPoint {
  const scale = clampViewportScale(transform.scale);
  const normalizedRotation = normalizeRotationDeg(transform.rotationDeg);

  const translated = {
    x: screenPoint.x - transform.translation.x,
    y: screenPoint.y - transform.translation.y,
  };

  const unrotated = rotatePoint(translated, -toRadians(normalizedRotation));

  return {
    x: unrotated.x / scale,
    y: unrotated.y / scale,
  };
}

export function screenFromWorld(worldPoint: ViewportPoint, transform: MapTransform): ViewportPoint {
  const scale = clampViewportScale(transform.scale);
  const normalizedRotation = normalizeRotationDeg(transform.rotationDeg);

  const scaled = {
    x: worldPoint.x * scale,
    y: worldPoint.y * scale,
  };

  const rotated = rotatePoint(scaled, toRadians(normalizedRotation));

  return {
    x: rotated.x + transform.translation.x,
    y: rotated.y + transform.translation.y,
  };
}

export function applyPanDelta(transform: MapTransform, delta: ViewportPoint): MapTransform {
  if (!isFiniteNumber(delta.x) || !isFiniteNumber(delta.y)) {
    return transform;
  }

  const nextTranslation = {
    x: transform.translation.x + delta.x,
    y: transform.translation.y + delta.y,
  };

  if (!isFiniteNumber(nextTranslation.x) || !isFiniteNumber(nextTranslation.y)) {
    return transform;
  }

  return {
    ...transform,
    translation: nextTranslation,
  };
}

export function applyPinchRotate(transform: MapTransform, input: PinchRotateInput): MapTransform {
  if (!isValidViewport(input.viewport)) {
    return transform;
  }

  if (
    !isFiniteNumber(input.scaleFactor) ||
    !isFiniteNumber(input.rotationDeltaDeg) ||
    input.scaleFactor <= 0
  ) {
    return transform;
  }

  const focalPoint = clampFocalPoint(input.focal, input.viewport);
  const worldAnchor = worldFromScreen(focalPoint, transform);

  const nextScale = clampViewportScale(transform.scale * input.scaleFactor);
  const nextRotation = normalizeRotationDeg(transform.rotationDeg + input.rotationDeltaDeg);

  const projectedAnchor = screenFromWorld(worldAnchor, {
    scale: nextScale,
    rotationDeg: nextRotation,
    translation: { x: 0, y: 0 },
  });

  const nextTranslation = {
    x: focalPoint.x - projectedAnchor.x,
    y: focalPoint.y - projectedAnchor.y,
  };

  if (!isFiniteNumber(nextTranslation.x) || !isFiniteNumber(nextTranslation.y)) {
    return transform;
  }

  return {
    scale: nextScale,
    rotationDeg: nextRotation,
    translation: nextTranslation,
  };
}

export function mapTransformsEqual(a: MapTransform, b: MapTransform): boolean {
  return (
    Math.abs(a.scale - b.scale) < EPSILON &&
    Math.abs(a.rotationDeg - b.rotationDeg) < EPSILON &&
    Math.abs(a.translation.x - b.translation.x) < EPSILON &&
    Math.abs(a.translation.y - b.translation.y) < EPSILON
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Image,
  PanResponder,
  Pressable,
  StyleSheet,
  Text,
  View,
  type LayoutChangeEvent,
  type PanResponderInstance,
} from 'react-native';

import {
  applyPanDelta,
  applyPinchRotate,
  createInitialMapTransform,
  mapTransformsEqual,
  type MapTransform,
  type ViewportDimensions,
  type ViewportPoint,
} from './mapTransform';

interface MapViewportProps {
  imageUri: string;
  onTransformChange?: (transform: MapTransform) => void;
}

interface GestureTracking {
  mode: 'none' | 'pan' | 'pinch';
  lastPanPoint: ViewportPoint | null;
  pinchStartDistance: number;
  pinchStartAngle: number;
  pinchStartTransform: MapTransform;
}

function touchPoint(touch: { locationX: number; locationY: number }): ViewportPoint {
  return {
    x: touch.locationX,
    y: touch.locationY,
  };
}

function distance(a: ViewportPoint, b: ViewportPoint): number {
  return Math.hypot(b.x - a.x, b.y - a.y);
}

function angle(a: ViewportPoint, b: ViewportPoint): number {
  return Math.atan2(b.y - a.y, b.x - a.x);
}

function midpoint(a: ViewportPoint, b: ViewportPoint): ViewportPoint {
  return {
    x: (a.x + b.x) / 2,
    y: (a.y + b.y) / 2,
  };
}

function formatTransformValue(value: number): string {
  if (!Number.isFinite(value)) {
    return '0';
  }

  return value.toFixed(2);
}

export function MapViewport({ imageUri, onTransformChange }: MapViewportProps) {
  const [viewport, setViewport] = useState<ViewportDimensions | null>(null);
  const [transform, setTransform] = useState<MapTransform>(createInitialMapTransform);

  const gesture = useRef<GestureTracking>({
    mode: 'none',
    lastPanPoint: null,
    pinchStartDistance: 0,
    pinchStartAngle: 0,
    pinchStartTransform: createInitialMapTransform(),
  });

  useEffect(() => {
    onTransformChange?.(transform);
  }, [onTransformChange, transform]);

  const commitTransform = useCallback((updater: (current: MapTransform) => MapTransform) => {
    setTransform((current) => {
      const next = updater(current);
      return mapTransformsEqual(current, next) ? current : next;
    });
  }, []);

  const panResponder: PanResponderInstance = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => true,
        onMoveShouldSetPanResponder: () => true,
        onPanResponderGrant: (event) => {
          const touches = event.nativeEvent.touches;

          if (touches.length >= 2) {
            const first = touches[0];
            const second = touches[1];
            if (!first || !second) {
              return;
            }

            const a = touchPoint(first);
            const b = touchPoint(second);
            gesture.current.mode = 'pinch';
            gesture.current.pinchStartDistance = distance(a, b);
            gesture.current.pinchStartAngle = angle(a, b);
            gesture.current.pinchStartTransform = transform;
            gesture.current.lastPanPoint = null;
            return;
          }

          const first = touches[0];
          if (!first) {
            return;
          }

          gesture.current.mode = 'pan';
          gesture.current.lastPanPoint = touchPoint(first);
        },
        onPanResponderMove: (event) => {
          const touches = event.nativeEvent.touches;

          if (touches.length >= 2) {
            const first = touches[0];
            const second = touches[1];
            if (!first || !second) {
              return;
            }

            const firstPoint = touchPoint(first);
            const secondPoint = touchPoint(second);

            if (gesture.current.mode !== 'pinch' || gesture.current.pinchStartDistance <= 0) {
              gesture.current.mode = 'pinch';
              gesture.current.pinchStartDistance = distance(firstPoint, secondPoint);
              gesture.current.pinchStartAngle = angle(firstPoint, secondPoint);
              gesture.current.pinchStartTransform = transform;
              gesture.current.lastPanPoint = null;
              return;
            }

            const currentDistance = distance(firstPoint, secondPoint);
            const currentAngle = angle(firstPoint, secondPoint);
            if (!Number.isFinite(currentDistance) || currentDistance <= 0 || !Number.isFinite(currentAngle)) {
              return;
            }

            const scaleFactor = currentDistance / gesture.current.pinchStartDistance;
            const rotationDeltaDeg = ((currentAngle - gesture.current.pinchStartAngle) * 180) / Math.PI;
            const focal = midpoint(firstPoint, secondPoint);

            commitTransform(() =>
              applyPinchRotate(gesture.current.pinchStartTransform, {
                scaleFactor,
                rotationDeltaDeg,
                focal,
                viewport,
              }),
            );

            return;
          }

          if (touches.length === 1) {
            const touch = touches[0];
            if (!touch) {
              return;
            }

            const point = touchPoint(touch);

            if (gesture.current.mode !== 'pan' || !gesture.current.lastPanPoint) {
              gesture.current.mode = 'pan';
              gesture.current.lastPanPoint = point;
              return;
            }

            const delta = {
              x: point.x - gesture.current.lastPanPoint.x,
              y: point.y - gesture.current.lastPanPoint.y,
            };

            commitTransform((current) => applyPanDelta(current, delta));
            gesture.current.lastPanPoint = point;
            return;
          }

          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
        },
        onPanResponderRelease: () => {
          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
          gesture.current.pinchStartDistance = 0;
        },
        onPanResponderTerminate: () => {
          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
          gesture.current.pinchStartDistance = 0;
        },
      }),
    [commitTransform, transform, viewport],
  );

  const onLayout = (event: LayoutChangeEvent) => {
    const { width, height } = event.nativeEvent.layout;
    if (width <= 0 || height <= 0) {
      return;
    }

    setViewport({ width, height });
  };

  const applyScaleAtViewportCenter = (scaleFactor: number) => {
    commitTransform((current) =>
      applyPinchRotate(current, {
        scaleFactor,
        rotationDeltaDeg: 0,
        focal: {
          x: viewport ? viewport.width / 2 : 0,
          y: viewport ? viewport.height / 2 : 0,
        },
        viewport,
      }),
    );
  };

  const applyRotationAtViewportCenter = (rotationDeltaDeg: number) => {
    commitTransform((current) =>
      applyPinchRotate(current, {
        scaleFactor: 1,
        rotationDeltaDeg,
        focal: {
          x: viewport ? viewport.width / 2 : 0,
          y: viewport ? viewport.height / 2 : 0,
        },
        viewport,
      }),
    );
  };

  return (
    <View style={styles.container}>
      <View style={styles.controls}>
        <Pressable onPress={() => applyScaleAtViewportCenter(1.2)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Zoom +</Text>
        </Pressable>
        <Pressable onPress={() => applyScaleAtViewportCenter(1 / 1.2)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Zoom -</Text>
        </Pressable>
        <Pressable onPress={() => applyRotationAtViewportCenter(-15)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Rotate ↺</Text>
        </Pressable>
        <Pressable onPress={() => applyRotationAtViewportCenter(15)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Rotate ↻</Text>
        </Pressable>
        <Pressable onPress={() => setTransform(createInitialMapTransform())} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Reset</Text>
        </Pressable>
      </View>

      <View style={styles.viewport} onLayout={onLayout} {...panResponder.panHandlers}>
        <Image
          source={{ uri: imageUri }}
          resizeMode="contain"
          style={[
            styles.mapImage,
            {
              transform: [
                { translateX: transform.translation.x },
                { translateY: transform.translation.y },
                { rotateZ: `${transform.rotationDeg}deg` },
                { scale: transform.scale },
              ],
            },
          ]}
        />
      </View>

      <Text style={styles.telemetry}>
        scale={formatTransformValue(transform.scale)} rotation={formatTransformValue(transform.rotationDeg)}° tx=
        {formatTransformValue(transform.translation.x)} ty={formatTransformValue(transform.translation.y)}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    width: '100%',
    flex: 1,
    gap: 8,
  },
  controls: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 6,
  },
  controlButton: {
    backgroundColor: '#0f172a',
    borderColor: '#334155',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 10,
    paddingVertical: 6,
  },
  controlButtonText: {
    color: '#e2e8f0',
    fontSize: 12,
    fontWeight: '600',
  },
  viewport: {
    flex: 1,
    minHeight: 280,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: '#334155',
    overflow: 'hidden',
    backgroundColor: '#020617',
  },
  mapImage: {
    width: '100%',
    height: '100%',
  },
  telemetry: {
    color: '#94a3b8',
    fontSize: 12,
    fontVariant: ['tabular-nums'],
  },
});

/**
 * MapViewportFloor — floor-switching extension of MapViewport.
 *
 * Composes:
 * - MapViewport (floor plan image with pan/pinch/rotate controls)
 * - Floor selector strip (horizontal ScrollView of floor buttons)
 * - RoutePathOverlay (polyline overlay on active floor)
 *
 * The active floor target is tracked in state and drives both
 * which image is shown and which floor segment is rendered.
 */

import { useCallback, useEffect, useState } from 'react';
import {
  FlatList,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import { MapViewport } from './MapViewport';
import { RoutePathOverlay, type RoutePathPoint } from '../components/route/RoutePathOverlay';
import type { FloorPlanTarget } from '../data/mapApiClient';
import type { MapTransform } from './mapTransform';
import type { ViewportDimensions } from './mapTransform';

/* ─── Props ─── */

export interface MapViewportFloorProps {
  /** MapViewport props */
  onTransformChange?: (transform: MapTransform) => void;
  /** All available floor targets for the active route */
  floorTargets: FloorPlanTarget[];
  /** Currently selected floor target */
  activeFloorTarget: FloorPlanTarget | null;
  /** Floor ID for the active target (used for route path overlay filtering) */
  activeFloorId: number;
  /** Route path waypoints (normalized coordinates) */
  routePath: RoutePathPoint[];
  /** Called when user presses a floor button */
  onFloorChange: (target: FloorPlanTarget) => void;
  /** Whether to show the route path overlay */
  showRouteOverlay?: boolean;
  /** Whether to show the floor selector strip */
  showFloorSelector?: boolean;
}

/* ─── State ─── */

interface FloorButtonData {
  target: FloorPlanTarget;
  label: string;
  isActive: boolean;
}

/* ─── Component ─── */

export function MapViewportFloor({
  onTransformChange,
  floorTargets,
  activeFloorTarget,
  activeFloorId,
  routePath,
  onFloorChange,
  showRouteOverlay = true,
  showFloorSelector = true,
}: MapViewportFloorProps) {
  const [transform, setTransform] = useState<MapTransform>({
    scale: 1,
    rotationDeg: 0,
    translation: { x: 0, y: 0 },
  });
  const [viewportDimensions, setViewportDimensions] = useState<ViewportDimensions>({ width: 300, height: 300 });

  const handleTransformChange = useCallback(
    (t: MapTransform) => {
      setTransform(t);
      onTransformChange?.(t);
    },
    [onTransformChange],
  );

  // Build floor button data
  const floorButtons: FloorButtonData[] = floorTargets.map(target => ({
    target,
    label: `Bldg ${target.buildingId} Fl ${target.floorNumber}`,
    isActive: activeFloorTarget !== null
      && activeFloorTarget.buildingId === target.buildingId
      && activeFloorTarget.floorNumber === target.floorNumber,
  }));

  return (
    <View style={styles.container}>
      {/* Map viewport with optional route overlay */}
      <View style={styles.mapContainer}>
        <MapViewport
          imageUri=""
          onTransformChange={handleTransformChange}
        />
        {showRouteOverlay && activeFloorTarget && (
          <RoutePathOverlay
            path={routePath}
            activeFloorId={activeFloorId}
            viewport={viewportDimensions}
            scale={transform.scale}
          />
        )}
      </View>

      {/* Floor selector strip */}
      {showFloorSelector && floorButtons.length > 0 && (
        <View style={styles.floorSelector}>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.floorScrollContent}
          >
            {floorButtons.map((btn, idx) => (
              <Pressable
                key={`floor-${idx}`}
                style={[styles.floorButton, btn.isActive && styles.floorButtonActive]}
                onPress={() => onFloorChange(btn.target)}
              >
                <Text style={[styles.floorButtonText, btn.isActive && styles.floorButtonTextActive]}>
                  {btn.label}
                </Text>
              </Pressable>
            ))}
          </ScrollView>
        </View>
      )}
    </View>
  );
}

/* ─── Styles ─── */

const styles = StyleSheet.create({
  container: {
    width: '100%',
    gap: 8,
  },
  mapContainer: {
    flex: 1,
    minHeight: 280,
    borderRadius: 12,
    overflow: 'hidden',
  },
  floorSelector: {
    paddingVertical: 4,
  },
  floorScrollContent: {
    flexDirection: 'row',
    gap: 8,
    paddingHorizontal: 4,
    paddingVertical: 4,
  },
  floorButton: {
    backgroundColor: '#0f172a',
    borderColor: '#334155',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 12,
    paddingVertical: 6,
  },
  floorButtonActive: {
    backgroundColor: '#0c2d4a',
    borderColor: '#38bdf8',
    borderWidth: 1.5,
  },
  floorButtonText: {
    color: '#94a3b8',
    fontSize: 12,
    fontWeight: '500',
  },
  floorButtonTextActive: {
    color: '#38bdf8',
    fontWeight: '700',
  },
});

/**
 * App — visitor navigation runtime (no sign-in required).
 *
 * Composition:
 * - Bootstrap: loads nav graph + campus image from configured endpoints
 * - DestinationPicker: building/floor/node search with start/destination selection
 * - MapViewportFloor: floor plan image viewer + route path overlay + floor switcher
 * - RoutePreview: step-by-step directions when route is ready
 * - Accessible mode toggle: switches between standard / accessible routing
 */

import { useCallback, useEffect, useState } from 'react';
import {
  ActivityIndicator,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import {
  IDLE_MAP_BOOTSTRAP_STATE,
  type MapBootstrapState,
  runMapBootstrap,
} from './bootstrap/mapBootstrapState';
import type { NormalizedNavGraph } from './domain/navGraph';
import { MapViewportFloor } from './map/MapViewportFloor';
import type { FloorPlanTarget } from './data/mapApiClient';
import { createMapApiClient } from './data/mapApiClient';
import {
  createInitialMapTransform,
  mapTransformsEqual,
  type MapTransform,
} from './map/mapTransform';
import { DestinationPicker } from './components/destination/DestinationPicker';
import { RoutePreview } from './components/route/RoutePreview';
import { RoutePathOverlay, type RoutePathPoint } from './components/route/RoutePathOverlay';
import { useRouteSelection } from './hooks/useRouteSelection';
import { useRouteSession } from './routing/useRouteSession';
import { useGuidanceSession } from './hooks/useGuidanceSession';
import { useCurrentPosition } from './hooks/useCurrentPosition';
import { LiveGuidanceOverlay } from './components/guidance/LiveGuidanceOverlay';
import { ConfidenceIndicator } from './components/guidance/ConfidenceIndicator';
import type { NavNode } from '@shared/types';

/* ─── Helpers ─── */

function nextAttemptFromState(state: MapBootstrapState): number {
  if (state.phase === 'idle') return 1;
  return state.attempt + 1;
}

function phaseMessage(state: MapBootstrapState): string {
  switch (state.phase) {
    case 'idle':    return 'Preparing startup checks.';
    case 'loading': return `Loading ${state.currentPhase} contract from ${state.endpoint}.`;
    case 'ready':   return 'CampusNav map is ready for visitor navigation.';
    case 'error':   return state.message;
  }
}

function formatMetric(value: number): string {
  return Number.isFinite(value) ? value.toFixed(2) : '0';
}

/* ─── Floor target from normalized graph ─── */

function buildFloorTargets(graph: NormalizedNavGraph): FloorPlanTarget[] {
  const targets: FloorPlanTarget[] = [];
  for (const building of graph.graph.buildings) {
    for (const floor of building.floors) {
      targets.push({ buildingId: building.id, floorNumber: floor.floorNumber });
    }
  }
  return targets;
}

/* ─── Map FloorPlanTarget → floorId ─── */

function getFloorId(target: FloorPlanTarget, graph: NormalizedNavGraph): number {
  const key = `${target.buildingId}:${target.floorNumber}`;
  return graph.floorByBuildingAndNumber.get(key)?.floor.id ?? 0;
}

/* ─── Route path from session ready state ─── */

function buildRoutePath(sessionPhase: 'ready', graph: NormalizedNavGraph): RoutePathPoint[] {
  if (!sessionPhase || sessionPhase !== 'ready') return [];
  return [];
}

/* ─── Component ─── */

export default function App() {
  const [bootstrapState, setBootstrapState] = useState<MapBootstrapState>(IDLE_MAP_BOOTSTRAP_STATE);
  const [transformState, setTransformState] = useState<MapTransform>(createInitialMapTransform());
  const [graph, setGraph] = useState<NormalizedNavGraph | null>(null);
  const [imageUri, setImageUri] = useState<string>('');
  const [activeFloorTarget, setActiveFloorTarget] = useState<FloorPlanTarget | null>(null);
  const [activeFloorId, setActiveFloorId] = useState<number>(0);
  const [routePath, setRoutePath] = useState<RoutePathPoint[]>([]);
  const [accessibleMode, setAccessibleMode] = useState(false);
  const [floorTargets, setFloorTargets] = useState<FloorPlanTarget[]>([]);

  /* ─── Bootstrap ─── */

  const executeBootstrap = useCallback(async (attempt: number) => {
    const result = await runMapBootstrap({ attempt });
    for (const t of result.transitions) {
      if (t.phase === 'loading') console.info('[mobile-bootstrap]', { phase: t.phase, attempt: t.attempt, currentPhase: t.currentPhase, endpoint: t.endpoint });
      if (t.phase === 'ready') console.info('[mobile-bootstrap]', { phase: t.phase, attempt: t.attempt, endpoint: t.image.endpoint });
      if (t.phase === 'error') console.warn('[mobile-bootstrap]', { phase: t.phase, attempt: t.attempt, failedPhase: t.failedPhase, reason: t.reason, recoverable: t.recoverable });
    }
    setBootstrapState(result.state);
  }, []);

  useEffect(() => {
    void executeBootstrap(1);
  }, [executeBootstrap]);

  /* ─── Graph already normalized by bootstrap ─── */

  useEffect(() => {
    if (bootstrapState.phase !== 'ready') return;
    const normalized = bootstrapState.graph;
    setGraph(normalized);
    const targets = buildFloorTargets(normalized);
    setFloorTargets(targets);
  }, [bootstrapState]);

  /* ─── Set initial active floor when floorTargets are first populated ─── */

  const [initialFloorSet, setInitialFloorSet] = useState(false);
  useEffect(() => {
    if (!initialFloorSet && floorTargets.length > 0 && graph) {
      const firstTarget = floorTargets[0];
      setActiveFloorTarget(firstTarget);
      setActiveFloorId(getFloorId(firstTarget, graph));
      setInitialFloorSet(true);
    }
  }, [initialFloorSet, floorTargets, graph]);

  /* ─── Map API client for floor images ─── */

  const mapClient = graph && bootstrapState.phase === 'ready'
    ? createMapApiClient({ baseUrl: bootstrapState.apiBaseUrl })
    : null;

  /* ─── Update floor image when activeFloorTarget changes ─── */

  useEffect(() => {
    if (!mapClient || !activeFloorTarget) { setImageUri(''); return; }
    const url = mapClient.resolveFloorPlanImageUrl(activeFloorTarget);
    setImageUri(url);
  }, [mapClient, activeFloorTarget]);

  /* ─── Route selection ─── */

  const selection = useRouteSelection();

  /* ─── Route session ─── */

  const { sessionState, routeMode, setRouteMode } = graph
    ? useRouteSession({ graph, selection })
    : { sessionState: null, routeMode: 'standard' as const, setRouteMode: () => {} };

  /* ─── Update route mode when accessibleMode changes ─── */

  useEffect(() => {
    setRouteMode(accessibleMode ? 'accessible' : 'standard');
  }, [accessibleMode, setRouteMode]);

  /* ─── Build route path when session is ready ─── */

  useEffect(() => {
    if (!sessionState || sessionState.phase !== 'ready' || !graph) {
      setRoutePath([]);
      return;
    }
    const { path } = sessionState;
    const waypoints: RoutePathPoint[] = [];
    for (const nodeId of path.nodeIds) {
      const record = graph.nodeById.get(nodeId);
      if (!record) continue;
      const node = record.node;
      waypoints.push({ x: node.x, y: node.y, floorId: record.floorId });
    }
    setRoutePath(waypoints);
  }, [sessionState, graph]);

  /* ─── Transform change handler ─── */

  const onTransformChange = useCallback((nextTransform: MapTransform) => {
    setTransformState(current =>
      mapTransformsEqual(current, nextTransform)
        ? current
        : { scale: nextTransform.scale, rotationDeg: nextTransform.rotationDeg, translation: { ...nextTransform.translation } },
    );
  }, []);

  /* ─── Node select handler ─── */

  const onNodeSelect = useCallback((node: NavNode) => {
    selection.setFromTap(node);
    if (graph) {
      const record = graph.nodeById.get(node.id);
      if (record) {
        const target = floorTargets.find(t => t.buildingId === record.buildingId && t.floorNumber === record.floorNumber);
        if (target) {
          setActiveFloorTarget(target);
          setActiveFloorId(getFloorId(target, graph));
        }
      }
    }
  }, [selection, graph, floorTargets]);

  /* ─── Accessible mode toggle ─── */

  const toggleAccessibleMode = useCallback(() => {
    setAccessibleMode(prev => !prev);
  }, []);

  /* ─── Retry handler ─── */

  const onRetryPress = useCallback(() => {
    void executeBootstrap(nextAttemptFromState(bootstrapState));
  }, [executeBootstrap, bootstrapState]);

  /* ─── Guidance session (active only when route is ready) ─── */

  const isRouteReady = sessionState?.phase === 'ready' && graph !== null;
  const { position } = useCurrentPosition();
  const { guidanceState, startGuidance, stopGuidance, confirmPosition } = isRouteReady
    ? useGuidanceSession({ graph, route: sessionState!, updateIntervalMs: 2000 })
    : { guidanceState: { phase: 'idle' } as ReturnType<typeof useGuidanceSession>['guidanceState'], startGuidance: () => {}, stopGuidance: () => {}, confirmPosition: (_nodeId: string) => {} };

  const showStartGuidance = sessionState?.phase === 'ready' && guidanceState.phase === 'idle';
  const showGuidanceOverlay = guidanceState.phase !== 'idle';

  /* ─── Phase: idle / loading ─── */

  if (bootstrapState.phase === 'idle' || bootstrapState.phase === 'loading') {
    return (
      <View style={styles.container}>
        <Text style={styles.title}>CampusNav</Text>
        <Text style={styles.subtitle}>Visitor runtime shell (no sign-in)</Text>
        <Text style={styles.statusLabel}>Bootstrap phase: {bootstrapState.phase}</Text>
        <Text style={styles.statusMessage}>{phaseMessage(bootstrapState)}</Text>
        {bootstrapState.phase === 'loading' && (
          <View style={styles.loadingRow}>
            <ActivityIndicator size="small" color="#38bdf8" />
            <Text style={styles.loadingText}>{bootstrapState.currentPhase}</Text>
          </View>
        )}
      </View>
    );
  }

  /* ─── Phase: error ─── */

  if (bootstrapState.phase === 'error') {
    return (
      <View style={styles.container}>
        <Text style={styles.title}>CampusNav</Text>
        <Text style={styles.statusLabel}>Bootstrap phase: error</Text>
        <Text style={styles.errorReason}>Failed phase: {bootstrapState.failedPhase}</Text>
        <Text style={styles.errorReason}>Reason: {bootstrapState.reason}</Text>
        <Text style={styles.errorReason}>Endpoint: {bootstrapState.endpoint ?? 'n/a'}</Text>
        <Pressable onPress={onRetryPress} style={styles.retryButton}>
          <Text style={styles.retryButtonText}>Retry startup</Text>
        </Pressable>
      </View>
    );
  }

  /* ─── Phase: ready ─── */

  return (
    <View style={styles.container}>
      {/* Guidance overlay (rendered above everything) */}
      {showGuidanceOverlay && (
        <View style={styles.guidanceOverlayContainer}>
          <LiveGuidanceOverlay
            guidanceState={guidanceState}
            onConfirmPosition={() => {
              // When in low-confidence, tapping the map confirms position.
              // For now, use the first route node as a fallback.
              if (sessionState?.phase === 'ready') {
                const firstNodeId = sessionState.path.nodeIds[0];
                if (firstNodeId) confirmPosition(firstNodeId);
              }
            }}
            onStopGuidance={stopGuidance}
          />
        </View>
      )}

      {/* Confidence indicator dot — top-right corner, always visible during guidance */}
      {showGuidanceOverlay && (
        <View style={styles.confidenceDotContainer}>
          <ConfidenceIndicator confidence={guidanceState.positionConfidence} />
        </View>
      )}

      <ScrollView contentContainerStyle={styles.scrollContent}>
        {/* Header */}
        <Text style={styles.title}>CampusNav</Text>
        <Text style={styles.subtitle}>Visitor runtime — no sign-in needed</Text>
        <Text style={styles.statusLabel}>Graph: {graph!.graph.buildings.length} buildings</Text>

        {/* Destination Picker */}
        <View style={styles.section}>
          <DestinationPicker
            graph={graph!}
            selection={selection}
            onNodeSelect={onNodeSelect}
          />
        </View>

        {/* Route Preview (when ready) */}
        {sessionState && sessionState.phase === 'ready' && (
          <View style={styles.section}>
            <RoutePreview
              directions={sessionState.directions}
              accessibleMode={accessibleMode}
            />
          </View>
        )}

        {/* Start Guidance button — visible when route ready and not yet guiding */}
        {showStartGuidance && (
          <Pressable style={styles.startGuidanceButton} onPress={startGuidance}>
            <Text style={styles.startGuidanceText}>Start Guidance</Text>
          </Pressable>
        )}

        {/* Session phase / route status */}
        {sessionState && (
          <View style={styles.sessionStatus}>
            <Text style={styles.statusLabel}>Route: {sessionState.phase}</Text>
            {sessionState.phase === 'no-route' && (
              <Text style={styles.statusMessage}>No path found between selected locations.</Text>
            )}
            {sessionState.phase === 'error' && (
              <Text style={styles.errorReason}>{sessionState.errorMessage}</Text>
            )}
          </View>
        )}

        {/* Map Viewport with floor switcher */}
        <View style={styles.section}>
          <MapViewportFloor
            activeFloorId={activeFloorId}
            floorTargets={floorTargets}
            activeFloorTarget={activeFloorTarget}
            routePath={routePath}
            onFloorChange={(target) => {
              setActiveFloorTarget(target);
              if (graph) setActiveFloorId(getFloorId(target, graph));
            }}
            showRouteOverlay={sessionState?.phase === 'ready'}
            showFloorSelector={floorTargets.length > 1}
            onTransformChange={onTransformChange}
          />
        </View>

        {/* Accessible mode toggle */}
        <View style={styles.toggleRow}>
          <Text style={styles.toggleLabel}>Accessible mode</Text>
          <Pressable
            style={[styles.toggleButton, accessibleMode && styles.toggleButtonActive]}
            onPress={toggleAccessibleMode}
          >
            <Text style={[styles.toggleButtonText, accessibleMode && styles.toggleButtonTextActive]}>
              {accessibleMode ? 'ON' : 'OFF'}
            </Text>
          </Pressable>
        </View>

        {/* Telemetry */}
        <Text style={styles.telemetryText}>
          viewport scale={formatMetric(transformState.scale)} rotation={formatMetric(transformState.rotationDeg)}°
          tx={formatMetric(transformState.translation.x)} ty={formatMetric(transformState.translation.y)}
        </Text>
      </ScrollView>
    </View>
  );
}

